// CE (copy-engine) transfer path for the 4D all-to-all: pitched cudaMemcpy2D/3DAsync straight into
// the peers' window addresses. The copies that cross a link run on the DMA engines and take no
// SMs, so they proceed while compute holds every SM rather than waiting for a block slot. This
// rank's own share does not cross a link and does compete; see transfer.hpp.
// It computes no offsets -- the addressing comes from build_plan in a2a_plan.cc.
#include <fast_ulysses/common.hpp>
#include <fast_ulysses/transfer.hpp>

#include <chrono>
#include <thread>

namespace ulysses {

namespace {

// Debug-only, armed from Python. 0 = off, which is the only state a normal build ever sees.
int64_t g_fault_delay_us = 0;

void CUDART_CB delay_payload(void* arg)
{
    std::this_thread::sleep_for(std::chrono::microseconds(reinterpret_cast<int64_t>(arg)));
}

// One CopyOp -> one CUDA call. The slice counts below are derived, not passed, because
// cudaMemcpy3DParms takes no slice stride (see push_batched).
void issue_copy(void* dst, const void* src, const CopyOp& op, cudaStream_t stream)
{
    if (op.depth <= 1) {
        ULYSSES_CUDA_CHECK(cudaMemcpy2DAsync(dst,
                                             static_cast<size_t>(op.dst_pitch),
                                             src,
                                             static_cast<size_t>(op.src_pitch),
                                             static_cast<size_t>(op.width),
                                             static_cast<size_t>(op.rows),
                                             cudaMemcpyDefault,
                                             stream));
        return;
    }
    cudaMemcpy3DParms parms = {};
    parms.srcPtr            = make_cudaPitchedPtr(const_cast<void*>(src),
                                       static_cast<size_t>(op.src_pitch),
                                       static_cast<size_t>(op.width),
                                       static_cast<size_t>(op.src_slice / op.src_pitch));
    parms.dstPtr            = make_cudaPitchedPtr(dst,
                                       static_cast<size_t>(op.dst_pitch),
                                       static_cast<size_t>(op.width),
                                       static_cast<size_t>(op.dst_slice / op.dst_pitch));
    parms.extent =
        make_cudaExtent(static_cast<size_t>(op.width), static_cast<size_t>(op.rows), static_cast<size_t>(op.depth));
    parms.kind = cudaMemcpyDefault;
    ULYSSES_CUDA_CHECK(cudaMemcpy3DAsync(&parms, stream));
}

}  // namespace

// Arm (delay_us > 0) or disarm (0) the "signal before payload" fault. TESTS ONLY.
//
// The operator depends on copy-engine writes being visible at the destination by the time the
// barrier kernel's release store announcing them arrives, which is undocumented, so the test for it
// is only worth as much as its negative control. Armed, launch_a2a_ce holds the payload back and
// skips the join onto the caller's stream, so the closing barrier publishes while the bytes are in
// flight. See test/distributed/ce_ordering.py.
void set_ce_fault(int64_t delay_us)
{
    g_fault_delay_us = delay_us;
}

void launch_a2a_ce(const void*                  src,
                   const std::vector<uint64_t>& peer_ptrs,
                   const A2APlan&               plan,
                   cudaStream_t                 xfer,
                   int                          rank,
                   cudaStream_t                 stream)
{
    const int      ws        = static_cast<int>(peer_ptrs.size());
    const uint8_t* src_bytes = static_cast<const uint8_t*>(src);
    // Fresh events every call -- do not hoist them onto the group. A shared event re-recorded
    // while earlier waits are still pending lets one of those waits resolve against a later record,
    // which makes the wait depend on the very stream it is blocking: a circular wait. Creating them
    // here is depth-safe, since a wait captures the dependency at call time and destroy defers.
    //
    // ONE STREAM for the remote copies, since they all leave through the same egress and separate
    // streams would only make them contend. This rank's OWN share crosses no link, so it can run
    // alongside them on the caller's stream -- hence the separate emit below. Peers are visited in
    // XOR-shift order, which pairs ranks up without coordination.
    const Event ready(cudaEventDisableTiming);
    ULYSSES_CUDA_CHECK(cudaEventRecord(ready, stream));

    auto emit = [&](int p, cudaStream_t on) {
        for (const CopyOp& op : plan.ops) {
            if (op.peer == p) {
                issue_copy(reinterpret_cast<uint8_t*>(peer_ptrs[p]) + op.dst_offset, src_bytes + op.src_offset, op, on);
            }
        }
    };

    ULYSSES_CUDA_CHECK(cudaStreamWaitEvent(xfer, ready, 0));
    // Fault injection (see set_ce_fault): hold the payload back so the flag cannot be behind it.
    if (g_fault_delay_us > 0) {
        ULYSSES_CUDA_CHECK(cudaLaunchHostFunc(xfer, delay_payload, reinterpret_cast<void*>(g_fault_delay_us)));
    }
    for (int k = 1; k < ws; ++k) {
        const int peer = rank ^ k;
        if (peer < ws) {
            emit(peer, xfer);
        }
    }
    // XOR only enumerates every peer when ws is a power of two; sweep for any it missed.
    if ((ws & (ws - 1)) != 0) {
        for (int p = 0; p < ws; ++p) {
            if (p != rank && (p ^ rank) >= ws) {
                emit(p, xfer);
            }
        }
    }
    emit(rank, stream);

    const Event done(cudaEventDisableTiming);
    ULYSSES_CUDA_CHECK(cudaEventRecord(done, xfer));
    // Skipping this join is the fault: the caller's stream then reaches the closing barrier, and
    // publishes, without waiting for the remote copies. Nothing else about the call changes.
    if (g_fault_delay_us == 0) {
        ULYSSES_CUDA_CHECK(cudaStreamWaitEvent(stream, done, 0));
    }
    // done and ready are destroyed here, in reverse declaration order, as they were by hand.
}

}  // namespace ulysses

#pragma once
/// @file
/// The two device-side pieces of one collective: the copy-engine transfer and the flag barrier.
/// Neither knows where the peer addresses came from -- the caller passes them in, which is what
/// keeps every communication library out of this translation unit.
#include <cstdint>
#include <cuda_runtime.h>
#include <fast_ulysses/a2a_plan.hpp>
#include <vector>

namespace ulysses {

/// @brief Issue `plan.ops` as pitched cudaMemcpy2D/3DAsync copies into the peers' windows.
///
/// Remote peers are serialised on `xfer` because they all leave through the same egress and
/// separate streams would only make them contend; this rank's own share crosses no link and runs
/// on `stream` alongside them. The transfer is joined back onto `stream` before returning.
///
/// The zero-SM property is a property of the REMOTE copies: a peer copy overlaps concurrent compute,
/// while a same-device copy competes with it for the same memory system. This rank's own share is a
/// same-device copy, and so is the copy-out on the copying path.
///
/// @param src        base of this rank's input tensor
/// @param peer_ptrs  peer p's window base, as addressed from this rank; `plan.ops` offsets are
///                   relative to it. Its size is the world size.
/// @param plan       what this rank sends, from build_plan()
/// @param xfer       the group's dedicated transfer stream
/// @param rank       this rank's index within `peer_ptrs`
/// @param stream     the caller's stream
void launch_a2a_ce(const void*                  src,
                   const std::vector<uint64_t>& peer_ptrs,
                   const A2APlan&               plan,
                   cudaStream_t                 xfer,
                   int                          rank,
                   cudaStream_t                 stream);

/// @brief Barrier across the group, over P2P-accessible flags.
///
/// A one-block spin kernel: rank r publishes its epoch into every peer's `flags[r]` with a release
/// store, then waits until its own `flags[0..ws-1]` have all reached that epoch. The epoch lives on
/// the device and is advanced by the kernel, so a captured graph advances it on replay too -- a
/// host-computed epoch would bake a constant into the graph and every replay would be satisfied by
/// stale state.
///
/// The layout inside each rank's flag region is `uint64 flags[ws]` followed by `uint64 epoch`, so
/// the caller must provide at least `(ws + 1) * 8` bytes and zero them before the first call.
///
/// @param stream     the stream to order the handshake on
/// @param flag_ptrs  peer p's flag region, as addressed from this rank. Its size is the world size.
/// @param rank       this rank's index within `flag_ptrs`
void fast_barrier(cudaStream_t stream, const std::vector<uint64_t>& flag_ptrs, int rank);

/// @brief TESTS ONLY: publish the closing flag before the payload has landed, on purpose.
///
/// The operator assumes a completed copy-engine write is visible at the destination by the time a
/// later kernel's release store announcing it arrives, which no vendor document guarantees. Arming
/// this (`delay_us > 0`) makes launch_a2a_ce hold the payload back and skip the join onto the
/// caller's stream, so the test for that assumption has a negative control. 0 disarms.
void set_ce_fault(int64_t delay_us);

}  // namespace ulysses

#pragma once
/// @file
/// Error checking shared by every translation unit here.
#include <c10/util/Exception.h>
#include <cuda_runtime.h>
#include <torch/version.h>

// torch 2.10 is the floor, checked here because every translation unit that touches torch includes
// this header. Below it the build fails in src/group.cc on a name lookup --
// c10d::symmetric_memory::get_signal_pad_size() becomes a free TORCH_API function in 2.10, and the
// handshake's placement inside the signal pad is computed from it -- which names neither torch nor
// a version.
static_assert(TORCH_VERSION_MAJOR > 2 || (TORCH_VERSION_MAJOR == 2 && TORCH_VERSION_MINOR >= 10),
              "fast-ulysses requires torch 2.10 or newer: the symmetric-memory signal pad size is "
              "read through c10d::symmetric_memory::get_signal_pad_size(), a free function only "
              "from 2.10 on. No version of this package builds against an older torch.");

namespace ulysses {

/// @brief Check a CUDA runtime call and throw (TORCH_CHECK) on failure, naming the call text and
/// the driver's error string. For kernel launches, pass cudaGetLastError().
#define ULYSSES_CUDA_CHECK(expr)                                                                                       \
    do {                                                                                                               \
        cudaError_t err_ = (expr);                                                                                     \
        TORCH_CHECK(err_ == cudaSuccess, "CUDA error (" #expr "): ", cudaGetErrorString(err_));                        \
    } while (0)

/// @brief A cudaEvent_t destroyed on scope exit.
///
/// Every create/destroy pair here has ULYSSES_CUDA_CHECK calls between it, so the hand-paired form
/// leaked one event per call that threw -- and a call throws exactly when something is already
/// going wrong and the process is likely to keep running.
class Event {
public:
    /// @param flags cudaEventDefault keeps timing, which is what the timed op needs.
    explicit Event(unsigned flags = cudaEventDefault)
    {
        ULYSSES_CUDA_CHECK(cudaEventCreateWithFlags(&event_, flags));
    }

    ~Event()
    {
        cudaEventDestroy(event_);  // unchecked: a destructor must not throw
    }

    Event(const Event&)            = delete;
    Event& operator=(const Event&) = delete;

    /// Implicit, so the call sites read as they did with the raw handle.
    operator cudaEvent_t() const
    {
        return event_;
    }

private:
    cudaEvent_t event_ = nullptr;
};

}  // namespace ulysses

