1	#include <fast_ulysses/a2a_plan.hpp>
2	
3	#include <algorithm>
4	#include <limits>
5	#include <stdexcept>
6	#include <string>
7	
8	namespace ulysses {
9	
10	namespace {
11	
12	[[noreturn]] void fail(const std::string& message)
13	{
14	    throw std::invalid_argument("fast_ulysses: " + message);
15	}
16	
17	// A peer's entry in seq_splits/head_splits is bounded by nothing, and a product that wraps gives a
18	// negative window_numel, which every downstream size check reads as "small enough".
19	int64_t checked_mul(int64_t a, int64_t b, const std::string& what)
20	{
21	    if (a != 0 && b > std::numeric_limits<int64_t>::max() / a) {
22	        fail(what + " overflows int64 (" + std::to_string(a) + " * " + std::to_string(b) + ")");
23	    }
24	    return a * b;
25	}
26	
27	int64_t checked_sum(const std::vector<int64_t>& values, const std::string& what)
28	{
29	    int64_t total = 0;
30	    for (int64_t v : values) {
31	        if (v > std::numeric_limits<int64_t>::max() - total) {
32	            fail(what + " overflows int64");
33	        }
34	        total += v;
35	    }
36	    return total;
37	}
38	
39	// checked_mul above covers window_numel, which is in ELEMENTS and bounds none of the BYTE
40	// quantities build_plan emits. Each of those -- offsets, pitches, widths, batch strides -- is a
41	// product of some of these five factors, so one bound covers them all, and signed overflow is UB
42	// rather than a negative that a later check might catch. An empty axis counts as 1: it stops a copy
43	// being emitted, it does not make the other factors smaller.
44	void check_byte_products(const A2ADims& dims, int64_t seq_total, int64_t head_total, int64_t elem_size)
45	{
46	    int64_t bound = 1;
47	    for (int64_t factor : {dims.b, seq_total, head_total, dims.d, elem_size}) {
48	        bound = checked_mul(bound, std::max<int64_t>(factor, 1), "the exchange in bytes");
49	    }
50	}
51	
52	std::vector<int64_t> exclusive_prefix_sum(const std::vector<int64_t>& values)
53	{
54	    std::vector<int64_t> offsets(values.size(), 0);
55	    int64_t              running = 0;
56	    for (size_t i = 0; i < values.size(); ++i) {
57	        offsets[i] = running;
58	        running += values[i];
59	    }
60	    return offsets;
61	}
62	
63	// Emit `depth` batch repetitions of `op`, `src_stride` / `dst_stride` bytes apart, as one 3D copy
64	// when that is both expressible and worth it, and as `depth` 2D copies otherwise.
65	//
66	// Only MULTI-ROW copies are fused: a single-row copy is a flat memcpy, and folding b of them into
67	// one 3D copy would move them onto the strided path, while a pitched copy is already strided and
68	// fusing removes (b-1) launches. cudaMemcpy3DParms also takes no slice stride -- it derives one as
69	// pitch * ysize -- so a stride is expressible only when it divides the pitch and fits the rows.
70	void push_batched(std::vector<CopyOp>& out, CopyOp op, int64_t depth, int64_t src_stride, int64_t dst_stride)
71	{
72	    const bool worth_fusing = depth > 1 && op.rows > 1;
73	    const bool expressible  = worth_fusing && op.src_pitch > 0 && op.dst_pitch > 0 && src_stride % op.src_pitch == 0
74	                             && dst_stride % op.dst_pitch == 0 && src_stride / op.src_pitch >= op.rows
75	                             && dst_stride / op.dst_pitch >= op.rows;
76	    if (expressible) {
77	        op.depth     = depth;
78	        op.src_slice = src_stride;
79	        op.dst_slice = dst_stride;
80	        out.push_back(op);
81	        return;
82	    }
83	    for (int64_t i = 0; i < depth; ++i) {
84	        CopyOp one = op;
85	        one.src_offset += i * src_stride;
86	        one.dst_offset += i * dst_stride;
87	        out.push_back(one);
88	    }
89	}
90	
91	}  // namespace
92	
93	int64_t A2ADims::seq_total() const
94	{
95	    return checked_sum(seq_splits, "seq_splits total");
96	}
97	
98	int64_t A2ADims::head_total() const
99	{
100	    return checked_sum(head_splits, "head_splits total");
101	}
102	
103	std::vector<int64_t> A2ADims::seq_offsets() const
104	{
105	    return exclusive_prefix_sum(seq_splits);
106	}
107	
108	std::vector<int64_t> A2ADims::head_offsets() const
109	{
110	    return exclusive_prefix_sum(head_splits);
111	}
112	
113	void A2ADims::validate() const
114	{
115	    if (world_size <= 0) {
116	        fail("world_size must be positive, got " + std::to_string(world_size));
117	    }
118	    if (rank < 0 || rank >= world_size) {
119	        fail("rank " + std::to_string(rank) + " out of range for world_size " + std::to_string(world_size));
120	    }
121	    if (b <= 0 || d <= 0) {
122	        fail("b and d must be positive, got b=" + std::to_string(b) + " d=" + std::to_string(d));
123	    }
124	    if (static_cast<int>(seq_splits.size()) != world_size) {
125	        fail("seq_splits has " + std::to_string(seq_splits.size()) + " entries, expected "
126	             + std::to_string(world_size));
127	    }
128	    if (static_cast<int>(head_splits.size()) != world_size) {
129	        fail("head_splits has " + std::to_string(head_splits.size()) + " entries, expected "
130	             + std::to_string(world_size));
131	    }
132	    // Zero-length shards are allowed (a rank can end up with no sequence), negatives are not.
133	    for (int p = 0; p < world_size; ++p) {
134	        if (seq_splits[p] < 0) {
135	            fail("seq_splits[" + std::to_string(p) + "] is negative");
136	        }
137	        if (head_splits[p] < 0) {
138	            fail("head_splits[" + std::to_string(p) + "] is negative");
139	        }
140	    }
141	}
142	
143	A2APlan build_plan(const A2ADims& dims, int mode, int64_t elem_size)
144	{
145	    dims.validate();
146	    if (elem_size <= 0) {
147	        fail("elem_size must be positive, got " + std::to_string(elem_size));
148	    }
149	    if (mode != kScatterHead && mode != kGatherHead) {
150	        fail("mode must be 0 (scatter head) or 1 (gather head), got " + std::to_string(mode));
151	    }
152	
153	    const int64_t              seq_total   = dims.seq_total();
154	    const int64_t              head_total  = dims.head_total();
155	    const std::vector<int64_t> seq_offset  = dims.seq_offsets();
156	    const std::vector<int64_t> head_offset = dims.head_offsets();
157	    const int64_t              s_me        = dims.seq_splits[dims.rank];
158	    const int64_t              n_me        = dims.head_splits[dims.rank];
159	    check_byte_products(dims, seq_total, head_total, elem_size);
160	    const int64_t d_bytes = dims.d * elem_size;
161	
162	    A2APlan plan;
