1	// CE (copy-engine) transfer path for the 4D all-to-all: pitched cudaMemcpy2D/3DAsync straight into
2	// the peers' window addresses. The copies that cross a link run on the DMA engines and take no
3	// SMs, so they proceed while compute holds every SM rather than waiting for a block slot. This
4	// rank's own share does not cross a link and does compete; see transfer.hpp.
5	// It computes no offsets -- the addressing comes from build_plan in a2a_plan.cc.
6	#include <fast_ulysses/common.hpp>
7	#include <fast_ulysses/transfer.hpp>
8	
9	#include <chrono>
10	#include <thread>
11	
12	namespace ulysses {
13	
14	namespace {
15	
16	// Debug-only, armed from Python. 0 = off, which is the only state a normal build ever sees.
17	int64_t g_fault_delay_us = 0;
18	
19	void CUDART_CB delay_payload(void* arg)
20	{
21	    std::this_thread::sleep_for(std::chrono::microseconds(reinterpret_cast<int64_t>(arg)));
22	}
23	
24	// One CopyOp -> one CUDA call. The slice counts below are derived, not passed, because
25	// cudaMemcpy3DParms takes no slice stride (see push_batched).
26	void issue_copy(void* dst, const void* src, const CopyOp& op, cudaStream_t stream)
27	{
28	    if (op.depth <= 1) {
29	        ULYSSES_CUDA_CHECK(cudaMemcpy2DAsync(dst,
30	                                             static_cast<size_t>(op.dst_pitch),
31	                                             src,
32	                                             static_cast<size_t>(op.src_pitch),
33	                                             static_cast<size_t>(op.width),
34	                                             static_cast<size_t>(op.rows),
35	                                             cudaMemcpyDefault,
36	                                             stream));
37	        return;
38	    }
39	    cudaMemcpy3DParms parms = {};
40	    parms.srcPtr            = make_cudaPitchedPtr(const_cast<void*>(src),
41	                                       static_cast<size_t>(op.src_pitch),
42	                                       static_cast<size_t>(op.width),
43	                                       static_cast<size_t>(op.src_slice / op.src_pitch));
44	    parms.dstPtr            = make_cudaPitchedPtr(dst,
45	                                       static_cast<size_t>(op.dst_pitch),
46	                                       static_cast<size_t>(op.width),
47	                                       static_cast<size_t>(op.dst_slice / op.dst_pitch));
48	    parms.extent =
49	        make_cudaExtent(static_cast<size_t>(op.width), static_cast<size_t>(op.rows), static_cast<size_t>(op.depth));
50	    parms.kind = cudaMemcpyDefault;
51	    ULYSSES_CUDA_CHECK(cudaMemcpy3DAsync(&parms, stream));
52	}
53	
54	}  // namespace
55	
56	// Arm (delay_us > 0) or disarm (0) the "signal before payload" fault. TESTS ONLY.
57	//
58	// The operator depends on copy-engine writes being visible at the destination by the time the
59	// barrier kernel's release store announcing them arrives, which is undocumented, so the test for it
60	// is only worth as much as its negative control. Armed, launch_a2a_ce holds the payload back and
61	// skips the join onto the caller's stream, so the closing barrier publishes while the bytes are in
62	// flight. See test/distributed/ce_ordering.py.
63	void set_ce_fault(int64_t delay_us)
64	{
65	    g_fault_delay_us = delay_us;
66	}
67	
68	void launch_a2a_ce(const void*                  src,
69	                   const std::vector<uint64_t>& peer_ptrs,
70	                   const A2APlan&               plan,
71	                   cudaStream_t                 xfer,
72	                   int                          rank,
73	                   cudaStream_t                 stream)
74	{
75	    const int      ws        = static_cast<int>(peer_ptrs.size());
76	    const uint8_t* src_bytes = static_cast<const uint8_t*>(src);
77	    // Fresh events every call -- do not hoist them onto the group. A shared event re-recorded
78	    // while earlier waits are still pending lets one of those waits resolve against a later record,
79	    // which makes the wait depend on the very stream it is blocking: a circular wait. Creating them
80	    // here is depth-safe, since a wait captures the dependency at call time and destroy defers.
81	    //
82	    // ONE STREAM for the remote copies, since they all leave through the same egress and separate
83	    // streams would only make them contend. This rank's OWN share crosses no link, so it can run
84	    // alongside them on the caller's stream -- hence the separate emit below. Peers are visited in
85	    // XOR-shift order, which pairs ranks up without coordination.
86	    const Event ready(cudaEventDisableTiming);
87	    ULYSSES_CUDA_CHECK(cudaEventRecord(ready, stream));
88	
89	    auto emit = [&](int p, cudaStream_t on) {
90	        for (const CopyOp& op : plan.ops) {
91	            if (op.peer == p) {
92	                issue_copy(reinterpret_cast<uint8_t*>(peer_ptrs[p]) + op.dst_offset, src_bytes + op.src_offset, op, on);
93	            }
94	        }
95	    };
96	
97	    ULYSSES_CUDA_CHECK(cudaStreamWaitEvent(xfer, ready, 0));
98	    // Fault injection (see set_ce_fault): hold the payload back so the flag cannot be behind it.
99	    if (g_fault_delay_us > 0) {
100	        ULYSSES_CUDA_CHECK(cudaLaunchHostFunc(xfer, delay_payload, reinterpret_cast<void*>(g_fault_delay_us)));
101	    }
102	    for (int k = 1; k < ws; ++k) {
103	        const int peer = rank ^ k;
104	        if (peer < ws) {
105	            emit(peer, xfer);
106	        }
107	    }
108	    // XOR only enumerates every peer when ws is a power of two; sweep for any it missed.
109	    if ((ws & (ws - 1)) != 0) {
110	        for (int p = 0; p < ws; ++p) {
111	            if (p != rank && (p ^ rank) >= ws) {
112	                emit(p, xfer);
113	            }
114	        }
115	    }
116	    emit(rank, stream);
117	
118	    const Event done(cudaEventDisableTiming);
119	    ULYSSES_CUDA_CHECK(cudaEventRecord(done, xfer));
120	    // Skipping this join is the fault: the caller's stream then reaches the closing barrier, and
121	    // publishes, without waiting for the remote copies. Nothing else about the call changes.
122	    if (g_fault_delay_us == 0) {
123	        ULYSSES_CUDA_CHECK(cudaStreamWaitEvent(stream, done, 0));
124	    }
125	    // done and ready are destroyed here, in reverse declaration order, as they were by hand.
126	}
127	
128	}  // namespace ulysses
