1	#pragma once
2	// Addressing for the 4D all-to-all, expressed as pitched copies. Pure host arithmetic with no CUDA,
3	// no torch and no communication library in it, so the layout contract can be tested on its own
4	// (test/test_plan.py replays
5	// a plan over numpy buffers). UNEVEN splits are the general case -- even splits are just
6	// seq_splits = [s/P]*P and head_splits = [n/P]*P -- so there is a single code path to get right.
7	#include <cstdint>
8	#include <vector>
9	
10	namespace ulysses {
11	
12	enum A2AMode : int {
13	    // [b, seq_splits[me], head_total, d] -> [b, seq_total, head_splits[me], d]
14	    kScatterHead = 0,
15	    // the inverse: [b, seq_total, head_splits[me], d] -> [b, seq_splits[me], head_total, d]
16	    kGatherHead = 1,
17	};
18	
19	struct A2ADims {
20	    int64_t              b          = 0;
21	    int64_t              d          = 0;
22	    int                  rank       = 0;
23	    int                  world_size = 0;
24	    std::vector<int64_t> seq_splits;   // per-rank local sequence length
25	    std::vector<int64_t> head_splits;  // per-rank head count
26	
27	    int64_t              seq_total() const;
28	    int64_t              head_total() const;
29	    std::vector<int64_t> seq_offsets() const;   // exclusive prefix sum of seq_splits
30	    std::vector<int64_t> head_offsets() const;  // exclusive prefix sum of head_splits
31	
32	    // Throws std::invalid_argument naming the offending field. Call before anything allocates.
33	    void validate() const;
34	};
35	
36	// One pitched copy, offsets in bytes from the base of their buffer (this rank's input tensor, the
37	// destination peer's symmetric window), so the same struct describes a cudaMemcpy2D/3DAsync and a
38	// host-side replay in a test. `depth` folds the batch dimension in: b repetitions of the same
39	// rows x width copy at a fixed stride go as ONE cudaMemcpy3DAsync, when expressible (push_batched).
40	struct CopyOp {
41	    int     peer       = 0;
42	    int64_t src_offset = 0;
43	    int64_t dst_offset = 0;
44	    int64_t src_pitch  = 0;
45	    int64_t dst_pitch  = 0;
46	    int64_t width      = 0;  // bytes per row
47	    int64_t rows       = 0;
48	    int64_t depth      = 1;  // batch elements folded into this op
49	    int64_t src_slice  = 0;  // bytes between batch elements, source
50	    int64_t dst_slice  = 0;  // bytes between batch elements, destination
51	};
52	
53	struct A2APlan {
54	    std::vector<int64_t> output_shape;  // shape THIS rank receives, dense from the window base
55	    // Elements the symmetric window must hold: the LARGEST rank's output, not this rank's. The peer
56	    // offsets only line up while every rank allocates the same size, and each rank can compute the
57	    // max without communicating, because the splits describe the whole group.
58	    int64_t             window_numel = 0;
59	    std::vector<CopyOp> ops;  // what THIS rank sends; ops[i].peer says where
60	};
61	
62	// One plan serves both entry points: `ops` covers all world_size destinations, so this rank's own
63	// share travels through the window like every peer's -- which is what the zero-copy path needs, the
64	// window BEING the caller's output, and what makes the copying path's copy-out one flat copy.
65	A2APlan build_plan(const A2ADims& dims, int mode, int64_t elem_size);
66	
67	}  // namespace ulysses
