1	// Exposes the pure-host plan builder to Python so test/test_plan.py can replay it over numpy
2	// buffers on a machine with no GPU. a2a_plan.cc itself stays free of torch and CUDA; this file is
3	// the only place the two meet. A separate TU is safe here, unlike the operator schemas in
4	// bindings.cc: this schema names no custom class, so static-initialisation order does not matter.
5	#include <ATen/ATen.h>
6	#include <torch/library.h>
7	#include <tuple>
8	
9	#include <fast_ulysses/a2a_plan.hpp>
10	
11	namespace ulysses {
12	namespace {
13	
14	// peer, src_off, dst_off, src_pitch, dst_pitch, width, rows, depth, src_slice, dst_slice
15	constexpr int64_t kOpFields = 10;
16	
17	std::tuple<std::vector<int64_t>, int64_t, at::Tensor> a2a_plan_debug(int64_t              b,
18	                                                                     int64_t              d,
19	                                                                     int64_t              rank,
20	                                                                     int64_t              world_size,
21	                                                                     std::vector<int64_t> seq_splits,
22	                                                                     std::vector<int64_t> head_splits,
23	                                                                     int64_t              mode,
24	                                                                     int64_t              elem_size)
25	{
26	    A2ADims dims;
27	    dims.b           = b;
28	    dims.d           = d;
29	    dims.rank        = static_cast<int>(rank);
30	    dims.world_size  = static_cast<int>(world_size);
31	    dims.seq_splits  = std::move(seq_splits);
32	    dims.head_splits = std::move(head_splits);
33	
34	    const A2APlan plan = build_plan(dims, static_cast<int>(mode), elem_size);
35	
36	    at::Tensor ops =
37	        at::empty({static_cast<int64_t>(plan.ops.size()), kOpFields}, at::TensorOptions().dtype(at::kLong));
38	    auto a = ops.accessor<int64_t, 2>();
39	    for (size_t i = 0; i < plan.ops.size(); ++i) {
40	        a[i][0] = plan.ops[i].peer;
41	        a[i][1] = plan.ops[i].src_offset;
42	        a[i][2] = plan.ops[i].dst_offset;
43	        a[i][3] = plan.ops[i].src_pitch;
44	        a[i][4] = plan.ops[i].dst_pitch;
45	        a[i][5] = plan.ops[i].width;
46	        a[i][6] = plan.ops[i].rows;
47	        a[i][7] = plan.ops[i].depth;
48	        a[i][8] = plan.ops[i].src_slice;
49	        a[i][9] = plan.ops[i].dst_slice;
50	    }
51	    return {plan.output_shape, plan.window_numel, ops};
52	}
