176	// Records the staging release on scope exit, INCLUDING when the transfer throws. Without it a
177	// throw after the copies were issued leaves the release event unrecorded, and the next call for
178	// that shape overwrites the staging buffer while the comm stream is still reading it -- silently,
179	// because waiting on an unrecorded event succeeds and does nothing.
180	struct StagingRelease {
181	    UlyssesGroup*          group;
182	    UlyssesGroup::Staging* slot;
183	    cudaStream_t           comm;
184	
185	    ~StagingRelease()
186	    {
187	        // The slot this call used, not "the last one staged": several calls of one shape can be in
188	        // flight, and each has to release its own.
189	        group->release_staging(slot, comm);  // noexcept; see the header
190	    }
191	};
