193	// Barrier, transfer, barrier: everything the call does to the window, ordered on `stream`.
194	void transfer_on_stream(const c10::intrusive_ptr<UlyssesGroup>& group, const Call& call, cudaStream_t stream)
195	{
196	    const int rank = static_cast<int>(group->rank());
197	
198	    // WRITERS WAIT FOR READERS, before writing anything. The window is single-buffered, so this
199	    // call is about to overwrite what the previous one produced, which a peer may still be
200	    // reading; the closing barrier below proves everyone's WRITES landed and nothing about their
201	    // READS. It guards the START of a call rather than the end of the previous one because on the
202	    // zero-copy path the result is read by the caller at a time the operator never sees.
203	    fast_barrier(stream, call.win->flag_ptrs, rank);
204	
205	    launch_a2a_ce(call.x.data_ptr(), call.win->peer_ptrs, *call.plan, group->xfer_stream(), rank, stream);
206	
207	    // That a completed peer memcpy is VISIBLE at the destination when this kernel's release store
208	    // arrives is an ASSUMPTION, not a documented guarantee -- test/distributed/ce_ordering.py is
209	    // the negative control for it.
210	    fast_barrier(stream, call.win->flag_ptrs, rank);
211	}
212	
213	// Window -> the caller's tensor, ordered after the closing barrier on the same stream. Every
214	// rank's result is dense from the window base, so this is one flat device-to-device copy -- this
215	// rank's own share included, since it travels through the window like every peer's.
216	void copy_out(const Call& call, cudaStream_t stream, int rank)
217	{
218	    ULYSSES_CUDA_CHECK(cudaMemcpyAsync(call.output.data_ptr(),
219	                                       reinterpret_cast<const void*>(call.win->peer_ptrs[rank]),
220	                                       static_cast<size_t>(call.output.nbytes()),
221	                                       cudaMemcpyDeviceToDevice,
222	                                       stream));
223	}
