225	at::Tensor run(const c10::intrusive_ptr<UlyssesGroup>&    group,
226	               const at::Tensor&                          input,
227	               int64_t                                    mode,
228	               const std::optional<std::vector<int64_t>>& seq_splits,
229	               const std::optional<std::vector<int64_t>>& head_splits,
230	               const std::optional<at::Tensor>&           out,
231	               WindowRole                                 role,
232	               cudaStream_t                               stream,
233	               bool                                       lend)
234	{
235	    const Call call = prepare(group, input, mode, seq_splits, head_splits, out, role, lend);
236	    transfer_on_stream(group, call, stream);
237	    if (!call.out_is_window) {
238	        copy_out(call, stream, static_cast<int>(group->rank()));
239	    }
240	    return call.output;
241	}
